import sys
import math

MOD = 10**9 + 7

def factorize(x):
    primes = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            primes.append(d)
            while x % d == 0:
                x //= d
        d += 1 if d == 2 else 2
    if x > 1:
        primes.append(x)
    return primes

def mod_pow(a, e, mod):
    res = 1
    while e > 0:
        if e & 1:
            res = res * a % mod
        a = a * a % mod
        e >>= 1
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    x = int(data[0])
    n = int(data[1])

    primes = factorize(x)
    ans = 1

    for p in primes:
        # compute exponent of p in the product over y=1..n
        # exponent = sum_{k>=1} floor(n / p^k)
        e = 0
        cur = p
        while cur <= n:
            e += n // cur
            if cur > n // p:
                break
            cur *= p
        ans = ans * mod_pow(p, e, MOD) % MOD

    print(ans)

if __name__ == "__main__":
    main()

