import sys
import math

MOD = 10**9 + 7

def factorize(x):
    primes = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            primes.append(d)
            while x % d == 0:
                x //= d
        d += 1 if d == 2 else 2  # check 2, then odd numbers
    if x > 1:
        primes.append(x)
    return primes

def mod_pow(a, e, mod):
    res = 1
    while e > 0:
        if e & 1:
            res = res * a % mod
        a = a * a % mod
        e >>= 1
    return res

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    x = int(data[0])
    n = int(data[1])

    primes = factorize(x)
    ans = 1

    for p in primes:
        # compute exponent of p in the product over y=1..n of g(y,p)
        e = 0
        t = p
        while t <= n:
            # number of y in [1,n] divisible by t
            cnt = n // t
            if cnt == 0:
                break
            e += cnt
            # move to next power of p, careful with overflow
            if t > n // p:
                break
            t *= p
        ans = ans * mod_pow(p, e, MOD) % MOD

    print(ans)

if __name__ == "__main__":
    main()
